          <Text className="text-white font-semibold">Sign Out</Text>
        </Pressable>
      ) : (
        <Pressable
          onPress={() => router.push('/sign-in')}
          className="bg-primary px-6 py-3 rounded-lg"
        >
          <Text className="text-white font-semibold">Sign In</Text>
        </Pressable>
      )}
    </View>
  );
}
